components.css:
.ds-nav {
  display: flex;
  gap: 24px;
  font-family: ui-monospace, "SF Mono", "SFMono-Regular", Consolas, monospace;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ds-nav-link {
  text-decoration: none;
  color: #0a0a0a;
  transition: color 0.2s;
  cursor: pointer;
}
.ds-nav-link:hover {
  color: #fa1900;
}

.ds-index-container {
  background: #f2f2ef;
  padding: 24px;
  font-family: sans-serif;
}
.ds-index-row {
  display: grid;
  grid-template-columns: 3.5rem 1fr 11rem 4rem;
  gap: 16px;
  align-items: baseline;
  padding: 28px 0;
  border-bottom: 1px solid #0a0a0a;
  text-decoration: none;
  color: #0a0a0a;
  transition: background 0.2s, padding 0.2s, margin 0.2s;
  cursor: pointer;
}
.ds-index-row:hover {
  background: #0a0a0a;
  color: #f2f2ef;
  padding-left: 12px;
  padding-right: 12px;
  margin: 0 -12px;
}
.ds-index-row:hover .ds-index-id {
  color: #fa1900;
}
.ds-index-id {
  font-family: monospace;
  font-size: 12px;
  font-weight: 700;
}
.ds-index-title {
  font-size: 24px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}
.ds-index-kind {
  font-size: 12.8px;
}
.ds-index-year {
  font-family: monospace;
  font-size: 12px;
  text-align: right;
}

.ds-site-card {
  width: 300px;
  font-family: sans-serif;
  text-decoration: none;
  color: #0a0a0a;
  display: block;
  cursor: pointer;
}
.ds-site-frame {
  display: block;
  aspect-ratio: 16 / 10;
  overflow: hidden;
  border: 1px solid #0a0a0a;
  background: #d9d9d5;
}
.ds-site-img {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #a0a0a0;
  color: #fff;
  font-weight: bold;
  font-size: 14px;
  filter: grayscale(100%) contrast(1.05);
  transition: filter 0.35s ease, transform 0.6s cubic-bezier(0.16, 1, 0.3, 1);
}
.ds-site-card:hover .ds-site-img {
  filter: none;
  transform: scale(1.03);
}
.ds-site-caption {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 8px;
  font-family: monospace;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
}
.ds-site-name .accent {
  color: #fa1900;
}
.ds-site-card:hover .ds-site-name {
  text-decoration: underline;
}
